\label{def:genhyp}
We say that a linear isomorphism $T:\mathbb{B}\to\mathbb{B}$ is \textit{generalized hyperbolic} if there exists a splitting $\mathbb{B} = E^s \oplus E^u$ into two closed subspaces such that for some $k>0$ conditions~\eqref{eq:HypContr} hold and
\begin{equation}\label{eq:GenHypIncl}
    T E^s \subset E^s, \quad T^{-1} E^u \subset E^u.
\end{equation}

\label{stat:difconj}
Let $f, h \in \mathfrak{D}(\mathbb{B})$ and assume that $f$ satisfies generalized hyperbolicity with constants $C>0$, $\lambda \in (0,1)$ and splitting $\mathbb{B} = E^s_x \oplus E^u_x$. 
Then:
\begin{itemize}
\item[(P1)] $\mathfrak{D}(\mathbb{B})$ is a group under composition, and $g = h \circ f \circ h^{-1}$
satisfies generalized hyperbolicity with constants $R_h^2 C$ and $\lambda$, where $R_h$ bounds $\|Dh\|$ and $\|Dh^{-1}\|$;
\item[(P2)] $f^{-1}$ satisfies generalized hyperbolicity with the same constants and with the splitting obtained by interchanging $E^s_x$ and $E^u_x$;
\item[(P3)] for every $n \geq 1$, $f^n$ satisfies generalized hyperbolicity with constants $C$, $\lambda^n$ and the same splitting;
\item[(P4)] let $p \in [1,+\infty]$ and let $f_i \in \mathfrak{D}(\mathbb{B}_i)$, $i \in \mathcal I$,
satisfy $f_i(0) = 0$, conditions \eqref{eq:C1-1}--\eqref{eq:C1-r2} with $R$ and $r$ independent of $i$, and generalized hyperbolicity with $C, \lambda$ independent of $i$.
Then $f(\{x_i\}) = \{f_i(x_i)\}$ belongs to $\mathfrak{D}(\mathbb{B})$, where
$\mathbb{B} = \bigl(\bigoplus_{i \in \mathcal I} \mathbb{B}_i\bigr)_{\ell^p}$, and satisfies generalized hyperbolicity with constants $C, \lambda$.
\end{itemize}

For $d>0$, we say that a sequence $\left\{y_{k} \in \mathbb{B}\right\}_{k \in I}$ is a $d$-pseudotrajectory if
\begin{equation}\label{eq:pst1}
\operatorname{dist}\left(y_{k+1}, f\left(y_{k}\right)\right) \leq d, \quad k \in \tilde{I}.
\end{equation}
If the interval $I$ is not specified, we assume that $I = \mathbb{Z}$.

\label{thm:main-results}
Let $f\in\mathfrak{D}(\mathbb{B})$ satisfy generalized hyperbolicity. Then:
\begin{enumerate}[
    label=\textup{(M\arabic*)},
    ref=\textup{M\arabic*}
]
    \item \label{item:main-LipSh}
    $f$ has the Lipschitz shadowing property;
    \item \label{item:main-LipPerSh}
    $f$ has the Lipschitz periodic shadowing property;
    \item \label{item:main-chain}
    periodic points are dense in the chain-recurrent set: $\overline{Per(f)}=CR(f)$;
    \item \label{item:main-robust}
    generalized hyperbolicity is robust in the uniform $C^1$
    distance: if $f$ satisfies generalized hyperbolicity with constants
    $C>0$ and $\lambda\in(0,1)$, then, for every
    $\lambda_1\in(\lambda,1)$, there exist $\delta>0$ and $C_1>0$ such
    that every $g\in\mathfrak{D}(\mathbb{B})$ satisfying
    $
    \|g-f\|_{C^1}<\delta
    $
    is generalized hyperbolic with constants $C_1$ and $\lambda_1$.
\end{enumerate}

We say that $f \in \mathfrak{D}(\mathbb{B})$ satisfies \textit{uniformly continuous generalized hyperbolicity} if it satisfies generalized hyperbolicity with a family of projections $\{P_x, Q_x\}$ for which the maps $x \to P_x$, $x \to Q_x$ are in addition uniformly continuous, i.e.
\begin{equation}\label{eq:cont-PQ}
    \mbox{$\forall$ $\varepsilon > 0$ $\exists$ $\delta > 0$ such that $\|P_x - P_y\|, \|Q_x - Q_y\| < \varepsilon$ for $|x-y| < \delta$}. 
\end{equation}

\label{thm:SS}
If $f \in \mathfrak{D}(\mathbb{B})$ satisfies uniformly continuous generalized hyperbolicity, then there exist $M>0$, $d_0 > 0$ such that for any $d \in (0, d_0)$ and diffeomorphism $g \in \mathfrak{D}(\mathbb{B})$ with $\|f-g\|_{C^1} < d$ the following holds.
    \begin{enumerate}[
    label=\textup{(S\arabic*)},
    ref=\textup{S\arabic*}
]
        \item \label{item:SS-semi}
            There exist uniformly continuous maps $h_1, h_2:\mathbb{B} \to \mathbb{B}$ satisfying
        \begin{equation}\label{eq:conj-h1}
        g \circ (Id+h_1) = (Id + h_1) \circ f,
        \end{equation}
        \begin{equation}\label{eq:conj-h2}
        f \circ (Id+h_2) = (Id + h_2) \circ g,
        \end{equation}
        \begin{equation}\label{eq:h1h2leqMdelta}
        |h_1(x)|, |h_2(x)| < Md, \quad x \in \mathbb{B},
        \end{equation}
        hence $f$ is uniformly semi-structurally stable.
        \item \label{item:SS-full}
        If additionally the spaces $E^s_x \oplus (Df(x))^{-1}E^u_{f(x)}$ do not depend on $x$, then $h_1$, $h_2$ can be chosen such that 
        \begin{equation}\label{eq:Idh-homeo}
        (Id+h_1) \circ (Id+h_2) = Id, \quad (Id+h_2) \circ (Id+h_1) = Id.
        \end{equation}
In that case, the maps $(Id+h_1)$, $(Id+h_2)$ are homeomorphisms, and hence $f$ is uniformly structurally stable.
    \end{enumerate}

\label{ex:shift}
    Let $\lambda \in (0, 1)$, $R > 1/\lambda$, $M > 1$  and diffeomorphisms $a_k: \mathbb{R} \to \mathbb{R}$ satisfy 
\begin{equation}\label{eq:shift-ak}
    a_k(0) = 0; \quad 
    a'_k(x) \in \left(\frac{1}{\lambda}, R\right), \; k < 0; \quad
    a'_k(x) \in \left(\frac{1}{R}, \lambda\right), \; k \geq 0,    
\end{equation}
\begin{equation}\label{eq:shift-akc2}
a_k \in C^2, \quad |a''_k|, |(a^{-1}_k)''| \leq M.
\end{equation}
Let $\mathbb{B} = \ell^p(\mathbb{Z})$ with $p \in [1, +\infty]$ and consider the map $f: \mathbb{B} \to \mathbb{B}$ defined as
$$
f(\{x_k\}) = \{y_k\}, \quad \mbox{where $y_{k+1} = a_k(x_k)$}.
$$
Then $f$ is a diffeomorphism satisfying generalized hyperbolicity.

\label{ex:coh}
Let $\mathbb{B} = L^p(\mathbb{S}^1, \mathbb{R})$ with $p \in [1, +\infty]$, or $\mathbb{B} = C^0(\mathbb{S}^1, \mathbb{R})$. Define a linear isomorphism $T:\mathbb{B} \to \mathbb{B}$, as 
\begin{equation}\label{eq:3-3-T}
T(v)(x) = w(x), \quad \mbox{with $w(g(x)) = a(x)v(x)$}.
\end{equation}
Then $T$ is generalized hyperbolic.

\label{stat:pushforward-Linfty}
    Let $f \in \mathfrak{D}(\mathbb{B})$ satisfy generalized hyperbolicity. Let $X = B(\mathbb{B}, \mathbb{B})$ be the Banach space of bounded maps $\mathbb{B} \to \mathbb{B}$ with the supremum norm. Consider the linear isomorphism $T_f: X \to X$ defined as follows
\begin{equation}\label{eq:3-3-Tf}
    T_fv(x) = w(x), \quad \mbox{with $w(f(x)) = Df(x)v(x)$}.    
\end{equation}
    Then $T_f$ is generalized hyperbolic.

\label{def:bs}
    We say that a sequence of operators $\mathcal{A} = \{A_{k\in I}:\mathbb{B} \to \mathbb{B}\}$ ($I$ as in \eqref{eq:I}) with uniformly bounded norms $\|A_k\|, \|A_k^{-1}\| \leq R$ satisfies the \textit{bounded solution property on interval $I$ with constant $L>0$} if  for any sequence $\{w_{k+1} \in \mathbb{B}\}_{k \in \tilde{I}}$ with $|w_{k+1}| \leq 1$ there exists a sequence $\{v_k \in \mathbb{B}\}_{k \in I}$ with $|v_k| \leq L$ such that
    \begin{equation}\label{eq:Inh}
    v_{k+1} = A_k v_k + w_{k+1}, \quad k \in \tilde{I}.        
    \end{equation}
    If $I = \mathbb{Z}$ we say that $\mathcal{A}$ satisfies the \textit{bounded solution property with constant $L>0$}.

\label{def:CLAk}
    Let $\mathcal{A} = \{A_k: \mathbb{B} \to \mathbb{B}\}_{k \in \mathbb{Z}}$ be a sequence of isomorphisms satisfying $\|A_k\|, \|A^{-1}_k\| \leq R$ for some $R>0$. We say that $\mathcal{A}$ satisfies \textit{generalized hyperbolicity} if there exist $C > 0$, $\lambda \in (0, 1)$ and  families of projections $P_k, Q_k: \mathbb{B} \to \mathbb{B}$ satisfying the following properties. Denote $E^s_k = P_k(\mathbb{B})$, $E^u_k = Q_k(\mathbb{B})$. For every $k \in \mathbb{Z}$ the following holds
\begin{itemize}
    \item[(GH1*)] \textbf{Splitting.} $P_k + Q_k = Id$, $\|P_k\|, \|Q_k\| \leq C$. Note that $E^s_k \oplus E^u_k = \mathbb{B}$.
    \item[(GH2*)] \textbf{Inclusion.} The spaces $E^s_k$ and $E^u_k$ are forward- and backward-invariant, respectively\footnote{Compare with condition (ED2), the only difference is inclusion instead of equality.}
    $$
    A_kE^s_k \subseteq E^s_{k+1}, \quad A_k^{-1}E^u_{k+1} \subseteq E^u_{k}.
    $$
    \item[(GH3*)] 

    \textbf{Exponential estimates.}  For every $n\ge 0$    
          \begin{align*}
             &\|\Phi_A(k+n, k)  v^s\|\le C\lambda^n\|v^s\|,
               && v^s\in E^s_k, \\
             &\|\Phi_A(k-n, k) v^u\|\le C\lambda^n\|v^u\|,
               && v^u\in E^u_k.
          \end{align*}
\end{itemize}
    For a periodic sequence of operators with period $m$ (i.e. $A_{k+m} = A_k$), we say that $\mathcal{A}$ satisfies \textit{periodic generalized hyperbolicity} if projections $P_k$, $Q_k$ are also $m$-periodic, that is, $P_{k+m} = P_k$, $Q_{k+m} = Q_k$.

\label{lem:orbitwise}
Let $f \in \mathfrak{D}(\mathbb{B})$, $C > 0$, $\lambda \in (0,1)$. Then $f$ satisfies generalized
hyperbolicity with constants $C, \lambda$ if and only if
\begin{itemize}
\item for every nonperiodic trajectory $\{x_k\}_{k \in \mathbb{Z}}$ of $f$, the sequence
$\{Df(x_k)\}_{k \in \mathbb{Z}}$ satisfies generalized hyperbolicity with constants $C, \lambda$;
\item for every $m$-periodic trajectory $\{x_k\}_{k \in \mathbb{Z}}$ of $f$, the sequence
$\{Df(x_k)\}_{k \in \mathbb{Z}}$ satisfies $m$-periodic generalized hyperbolicity with constants
$C, \lambda$.
\end{itemize}

\label{lem:Bk-Inf}
    Let $\mathcal A=\{A_k\}_{k\in\mathbb{Z}}$ be a sequence of linear isomorphisms such that $\|A_k\|,\|A_k^{-1}\|\leq R$.
 Assume that there exists $L>0$ such that for any finite interval $I = (a, b)$ the sequence $\{A_k\}_{k \in I}$ satisfies the bounded solution property on $I$ with constant $L$. Then the complete sequence $\{A_k\}_{k \in \mathbb{Z}}$ satisfies the bounded solution property on $\mathbb{Z}$ with the constant $2L$.

\label{lem:SBS-periodic}
Assume that $\mathcal{A} = \{A_k\}_{k \in \mathbb{Z}}$ is $m$-periodic ($A_{k+m}=A_k$, $k \in \mathbb{Z}$) and satisfies generalized hyperbolicity with constants $C, \lambda$, with a not necessarily periodic splitting. Then there exists $L = L(C, \lambda)>0$ such that for every bounded $m$-periodic sequence 
$w=\{w_k\}_{k\in\mathbb{Z}}\subset\mathbb{B}$ with $|w_k| \leq 1$ there exists an $m$-periodic sequence $v=\{v_k\}_{k\in\mathbb{Z}}\subset\mathbb{B}$, satisfying 
\begin{equation}\label{eq:inhom-diff}
v_{k+1}=A_k v_k + w_{k+1}, \quad |v_k| \leq L \qquad k\in\mathbb{Z}.
\end{equation}

\label{lem:CL-robust-Ak}
Assume that $\mathcal{A}=\{A_k\}$ satisfies generalized hyperbolicity
with constants $C>0$, $\lambda\in(0,1)$ and $\|A_k\|,\|A_k^{-1}\|\leq R$, for $k\in\mathbb{Z}$. 
Then for any $\lambda_1 \in (\lambda, 1)$, there exist $C_1 = C_1(C, \lambda, \lambda_1, R)$ and $\varepsilon > 0$ such that 
    \begin{itemize}
        \item[(Robust1)]  any sequence $\mathcal{B} = \{B_k\}_{k \in \mathbb{Z}}$, where 
\begin{equation}\label{eq:AkBk}
        \|B_k - A_k\| < \varepsilon, \quad k \in \mathbb{Z}  
\end{equation}
        also satisfies generalized hyperbolicity with constants $C_1$, $\lambda_1$;
        \item [(Robust2)] if, in addition, the sequence $\mathcal{A}$ is $m$-periodic and satisfies periodic generalized hyperbolicity, then any $m$-periodic sequence $\mathcal{B} = \{B_k\}_{k \in \mathbb{Z}}$ satisfying \eqref{eq:AkBk} also satisfies periodic generalized hyperbolicity with constants $C_1$, $\lambda_1$.
    \end{itemize}

\label{ex:CL-not-ED}
    Let $\mathbb{B} = \ell^p(\mathbb{Z})$, $p \in [1, \infty]$. Consider a sequence of operators $\mathcal{A} = \{A_k: \mathbb{B} \to \mathbb{B}\}_{k \in \mathbb{Z}}$ defined as
    $$
(A_k x)_m =
\begin{cases}
\dfrac{1}{2} x_m, & m \leq k, \\
2 x_m, & m > k.
\end{cases}    
    $$
    Then $\mathcal{A}$ satisfies generalized hyperbolicity, but does not admit an exponential dichotomy on $\mathbb{Z}^+$ or $\mathbb{Z}^-$.

We use the following statement for linear isomorphisms of Banach spaces.
\begin{thm}[{\cite[Theorem 1]{NilsonPeris}}]\label{thm:Bernandes-shadowing}
    For any invertible continuous linear operator $T$ on any Banach space $X$, if $T$ has the finite Lipschitz shadowing property with constant $L$, then $T$ has the Lipschitz shadowing property with constant $2L$.
\end{thm}
\begin{remark}
    The statement of Theorem 1 in \cite{NilsonPeris} gives only the shadowing property without specifying the constant. However, the proof can be repeated to establish the constant $2L$. For completeness of exposition we provide the proof tracing the constant in Appendix A.
\end{remark}

Consider the Banach space$
\mathfrak{X} =\ell^{\infty}(\mathbb{Z}, \mathbb{B})=\bigl\{\{v_n\}_{n\in\mathbb{Z}}: v_n\in \mathbb{B} \bigr\}
$
and a linear operator $\mathfrak{A} \colon \mathfrak{X} \to \mathfrak{X}$ defined by
$$
\mathfrak{A}\{v_n\}=\{v_n'\}, \qquad \text{where }\; v_{n+1}'=A_n v_n.
$$

Let us prove that under the assumptions of Lemma \ref{lem:Bk-Inf}, the operator $\mathfrak{A}$ has the finite shadowing property. 

Consider a finite interval $[k_1, k_2]$ and sequences $\xi^k\in \mathfrak{X}$, $k \in [k_1, k_2]$, with $|\xi^k|\leq1$; denote by $\xi_n^k \in \mathbb{B}$ ($k\in[k_1,k_2]$, $n\in\mathbb{Z}$) their elements.
Below we show that there exists a sequence $\nu^k \in \mathfrak{X}$, $k\in[k_1,k_2]$ with $|\nu^k| \leq L$ such that
\begin{equation}\label{eq:nu}
  \nu^{k+1}=\mathfrak{A}\nu^k+\xi^k,\quad k \in [k_1, k_2-1].
\end{equation}
Denote the elements of $\nu^k$ by $\nu^k_n \in \mathbb{B}$, i.e. $\nu^k = \{\nu^k_n\}$.
Equations \eqref{eq:nu} are equivalent to
\begin{equation}\label{eq:1-inf}
  \nu_{n+1}^{k+1}=A_n \nu_n^k+\xi_{n+1}^k, \qquad n \in \mathbb{Z},\; k \in [k_1,k_2-1].
\end{equation}

The idea is to read the doubly-indexed system \eqref{eq:1-inf} along the diagonals $k-n=j$: on each of them it becomes a finite inhomogeneous difference equation in the single index $n$ for the operators $\{A_n\}$, to which the finite bounded solution property applies.
Denote $j := k-n$ and consider the sequences
\begin{equation}\label{eq:1.5}
  \mu_n^j := \nu_n^{j+n},\qquad \theta_n^j := \xi_n^{j+n-1}.
\end{equation}

Then \eqref{eq:1-inf} is equivalent to
\begin{equation}\label{eq:2}
  \mu_{n+1}^j = A_n\mu_n^j+\theta_{n+1}^j,\qquad n\in\mathbb{Z},\; n+j\in[k_1,k_2-1].
\end{equation}
Rewriting indexes we have
\begin{equation}\label{eq:2'}
  \mu_{n+1}^j = A_n\mu_n^j+\theta_{n+1}^j,\qquad j\in\mathbb{Z},\; n\in[k_1-j,\,k_2-j-1].
\end{equation}

For any $j\in\mathbb{Z}$, according to \eqref{eq:Inh} there exists a sequence $\mu^j_n$ satisfying \eqref{eq:2'}, and $|\mu_n^j| \le L$ for $n\in[k_1-j,k_2-j]$.
Hence, for all $j\in\mathbb{Z}$ and $n+j\in[k_1,k_2-1]$, \eqref{eq:2} holds, which means that $\nu_n^k$ defined by \eqref{eq:1.5} satisfies \eqref{eq:1-inf}. Hence, the operator $\mathfrak{A}$ has the finite Lipschitz  shadowing property with constant $L$. According to Theorem \ref{thm:Bernandes-shadowing}, this implies that $\mathfrak{A}$ has the Lipschitz shadowing property with constant $2L$.

Let us now show that the sequence $\mathcal{A}$ satisfies the bounded solution property for $I = \mathbb{Z}$. Indeed, fix $\{w_k \in \mathbb{B}\}$ with $|w_k| \leq 1$. Consider the sequence $\xi^k \in \mathfrak{X}$ defined as 
$$
\xi^k = \{ \dots, w_{k+1}, w_{k+1}, w_{k+1}, \dots\}, \; \xi^k_n = w_{k+1}, \quad n\in \mathbb{Z}.
$$
Note that $|\xi^k| = |w_{k+1}| \leq 1$. Since $\mathfrak{A}$ has the shadowing property, there exists a sequence $\nu^k \in \mathfrak{X}$ with $|\nu^k| \leq 2L$ such that
\begin{equation}\label{eq:nu-inf}
  \nu^{k+1}=\mathfrak{A}\nu^k+\xi^k,\quad k \in \mathbb{Z}.
\end{equation}
Denote $\nu^k = \{\nu^k_n\}$, then $|\nu^k_n| \leq 2L$. According to \eqref{eq:nu-inf}, the sequence  $v_k = \nu^k_k$ satisfies \eqref{eq:Inh} for $I = \mathbb{Z}$ and hence $\mathcal{A}$ satisfies the bounded solution property with constant $2L$ for $I = \mathbb{Z}$.

If a sequence of operators $H_k: E_k^s \to F_k^u$ satisfies
\begin{equation}\label{eq:StHk}
        A_k^{uu}H_k = H_{k+1}A_k^{ss} - \Delta_k^{us} - \Delta_k^{uu}H_k + H_{k+1}A_k^{su}H_k + H_{k+1}\Delta_k^{ss} + H_{k+1}\Delta_k^{su}H_k
\end{equation}
    then inclusions \eqref{eq:ETildaIncl} hold.

Let $M = 2L$. Fix $d_0 > 0$, satisfying the following inequalities 
\begin{equation}\label{eq:M2'}
    L + 2(RM+R)(RM+R+L)\cdot r\left((RM+R+L)d_0\right) \leq M, 
\end{equation}
\begin{equation}\label{eq:M2''}
 2 (RM+R+L) \cdot r\left((RM+R+L)d_0\right) < 1.
\end{equation}
We first prove the statement for intervals of the form $[-N,N]$.
\begin{lem}\label{lem:NLipSh}
    For any $d < d_0$ and any $d$-pseudotrajectory $\{y_k\}_{k \in [-N, N]}$ there exists an exact trajectory $\{x_k\}_{k \in [-N, N]}$ such that
    $
    |y_k - x_k| \leq Md
    $.
\end{lem}
\begin{proof}
We prove the claim by induction on $N$. For $N=0$, the statement is immediate.

Consider a $d$-pseudotrajectory $\{y_{k \in [-(N+1), N+1]}\}$ with $d<d_0$. 
By the induction hypothesis, the $d$-pseudotrajectory $\{y_{k \in [-N, N]}\}$ is $Md$-shadowed by an exact trajectory $\{p_{k \in [-N, N]}\}$
\begin{equation}\label{Add4.1}
|y_k - p_k| \leq M d, \quad k \in [-N, N].
\end{equation}
Note that $p_{N+1} = f(p_N)$, $p_{-(N+1)} = f^{-1}(p_{-N})$. Due to \eqref{eq:C1-2}, \eqref{eq:pst1}, \eqref{eq:pst2} the following estimates hold
\begin{equation}\label{Add4.2}
|y_{N+1} - p_{N+1}| \leq (RM+1)d, \quad |y_{-(N+1)} - p_{-(N+1)}| \leq (RM+R)d.
\end{equation}
Hence, we conclude the following.
\begin{statement}\label{stat:dn+1}
For  $d< d_0$ a $d$-pseudotrajectory $\{y_{k \in [-(N+1), N+1]}\}$ can be $(RM+R)d$-shadowed.   
\end{statement}

In the following, we show how to construct a better shadowing trajectory.
Denote $A_k = Df(p_k)$. Consider the sequence $\{w_k \in \mathbb{B}\}$ defined by
$$
y_{k+1} - f(y_k) = - d w_{k+1}, \quad k \in [-(N+1), N], 
$$
$$
w_{k+1} = 0, \quad k \notin [-(N+1), N].
$$
Note that $|w_k| \leq 1$.
By Lemma \ref{lem:SBS} there exists a sequence $\{v_k \in \mathbb{B}\}_{k \in \mathbb{Z}}$, $|v_k| \leq L$ such that equalities \eqref{eq:Inh} hold.
Consider the sequence $z_k = y_k + dv_k$. Note that 
$$
f(z_k) = f(y_k + dv_k) = f(p_k + (y_k-p_k) +dv_k), \quad k \in [-(N+1), N+1].
$$
Inequalities \eqref{eq:C1-1}, \eqref{eq:C1-2}, \eqref{Add4.1}, \eqref{Add4.2} imply that
\begin{multline*}
|f(z_k) - (f(p_k) + A_k (y_k - p_k + dv_k) )| \leq |y_k - p_k + dv_k|r(|y_k - p_k + dv_k|) \leq \\ (RM+R+L)d \cdot r\left((RM+R+L)d\right).    
\end{multline*}
Then for $k \in [-(N+1), N]$ the following inequalities hold
\begin{multline*}
|z_{k+1} - f(z_k)| = |y_{k+1} + dv_{k+1} - p_{k+1} - \\ A_k (y_k - p_k + dv_k) - (f(z_k) - (f(p_k) + A_k (y_k - p_k + dv_k) ))|  \leq \\  
|y_{k+1}  - p_{k+1} + dw_{k+1} - A_k (y_k - p_k)| +|f(z_k) - (f(p_k) + A_k (y_k - p_k + dv_k) )| \leq \\  
|f(y_k) - f(p_k) - A_k (y_k - p_k)| + (RM+R+L)d \cdot r\left((RM+R+L)d\right) \leq \\
|y_k - p_k|r(|y_k - p_k|) + (RM+R+L)d \cdot r\left((RM+R+L)d\right) \leq \\ 
(RM+R)d\cdot r((RM+R)d) + (RM+R+L)d \cdot r\left((RM+R+L)d\right) \leq \\
2 (RM+R+L)d \cdot r\left((RM+R+L)d\right).
\end{multline*}
Hence $\{z_{k \in [-(N+1), N+1]}\}$ is a $2 (RM+R+L)d \cdot r\left((RM+R+L)d\right)$-pseudotrajectory. Inequality~\eqref{eq:M2''} implies 
$
2 (RM+R+L)d \cdot r\left((RM+R+L)d\right) < d_0
$.
According to Proposition \ref{stat:dn+1} the pseudotrajectory $\{z_{k \in [-(N+1), N+1]}\}$ can be $2(RM+R)(RM+R+L)d \cdot r\left((RM+R+L)d\right)$-shadowed by an exact trajectory $q_{k \in [-(N+1), N+1]}$. Then by \eqref{eq:M2'}
\begin{multline*}
|y_k - q_k| \leq |y_k - z_k| + |z_k-q_k| \leq \\ Ld + 2(RM+R)(RM+R+L)d \cdot r\left((RM+R+L)d\right) \leq Md    
\end{multline*}
and the pseudotrajectory $\{y_{k \in [-(N+1), N+1]}\}$ is $Md$-shadowed by $\{q_{k \in [-(N+1), N+1]}\}$, which completes the induction step and proves Lemma \ref{lem:NLipSh}.
\end{proof}

Every finite interval $I\subset\mathbb{Z}$ is contained in $[-N,N]$ for some $N>0$.
Restricting the trajectory supplied by Lemma~\ref{lem:NLipSh} to $I$ proves Lemma~\ref{lem:FinLipSh}.

By \eqref{eq:C1-r2} there exists $d_0 \in (0, d_1)$ such that
\begin{equation}\label{eq:1.1'}
    M\cdot r(Md_0) < \frac{1}{2}.
\end{equation}
\begin{statement}\label{stat:d2}
    For $d_0$ satisfying \eqref{eq:1.1'} and any $d$-pseudotrajectory $\{y_k\}_{k \in \mathbb{Z}}$ with $d<d_0$ there exists $d/2$-pseudotrajectory $\{z_k\}_{k \in \mathbb{Z}}$ such that
    \begin{equation}\label{eq:d2}
    |y_k-z_k| < Md.
    \end{equation}
