    Consider a $d$-pseudotrajectory $\{y_k\}$ with $d < d_0$. Similarly to the proof of Lemma~\ref{lem:FinLipSh} consider the sequence $\{w_{k \in \mathbb{Z}}\}$ defined by
\begin{equation}\label{eq:defw}
    y_{k+1}-f(y_k) = -dw_{k+1}, \quad k \in \mathbb{Z}.
\end{equation}
    Consider $B_k = Df(y_k)$. By the assumptions of Lemma \ref{lem:BS-SH} there exists a sequence $v_k \in \mathbb{B}$ such that
    $$
    v_{k+1} - B_kv_k = w_{k+1}, \quad |v_k| \leq M, \quad k \in \mathbb{Z}.
    $$
 Consider the sequence $\{z_k = y_k + dv_k\}_{k \in \mathbb{Z}}$. By construction, $\{z_k\}$ satisfies \eqref{eq:d2}. We now show that $\{z_k\}$ is a $d/2$-pseudotrajectory. By the construction of the sequence $\{v_k\}$ we have
    \begin{equation}\label{eq:zkBk}
        y_{k+1} + dv_{k+1} - (f(y_k) + B_kdv_k) = 0.
    \end{equation}
     Due to \eqref{eq:C1-1}, \eqref{eq:1.1'} and \eqref{eq:zkBk} the following inequalities hold
\begin{multline*}
|z_{k+1} - f(z_k)| = |y_{k+1} + dv_{k+1} - (f(y_k)+B_kdv_k) - (f(y_k+dv_k) - f(y_k) -B_kdv_k)|  = \\
|f(y_k+dv_k) - f(y_k) -B_kdv_k| \leq d|v_k|r(d|v_k|) \leq Md \cdot r(Md) \leq \frac{d}{2}.
