The proof of Theorem~\ref{thm:main-results}\,(\ref{item:main-robust}) combines Theorem~\ref{thm:main-results}\,(\ref{item:main-LipSh})--(\ref{item:main-LipPerSh}) with the robustness of generalized hyperbolicity for sequences of operators (Lemma~\ref{lem:CL-robust-Ak}).

Indeed, consider a diffeomorphism $f:\mathbb{B} \to \mathbb{B}$ satisfying generalized hyperbolicity with constants $C, \lambda$. Fix $\lambda_1 \in (\lambda, 1)$. 
For any trajectory $\{x_k\}$, the sequence of linear operators $\{Df(x_k)\}$ satisfies generalized hyperbolicity. Take $M, d_0 > 0$ as in Theorem~\ref{thm:main-results}\,
(\ref{item:main-LipSh})--(\ref{item:main-LipPerSh}) and $\varepsilon > 0, C_1 > C$ provided by Lemma~\ref{lem:CL-robust-Ak}. Choose $\delta \in (0, \min(d_0, \varepsilon/2))$ such that 
\begin{equation}\label{eq:delta1}
    \|Df(x)-Df(y)\| \leq \varepsilon/2, \quad |x-y| < M\delta.
\end{equation}
Let $g\in\mathfrak{D}(\mathbb{B})$ satisfy
\begin{equation}\label{eq:delta2}
\|f-g\|_{C^1}<\delta.
\end{equation}

Consider the set $\mathcal{O}$ of all trajectories of the diffeomorphism $g$. For any trajectory $\omega \in \mathcal{O}$ choose a point $y_{\omega} \in \omega$. 

We now construct spaces $E_y^{s, u}$ for all points $y \in \omega$. Consider an exact trajectory $y_{k\in \mathbb{Z}}$ of diffeomorphism $g$ with $y_0 = y_{\omega}$.
Note that $|y_{k+1} - f(y_k)| = |g(y_k) - f(y_k)| \leq \delta$, $k \in \mathbb{Z}$, hence $y_k$ is a $\delta$-pseudotrajectory of the diffeomorphism $f$. Denote $B_k = Dg(y_k)$. Consider two cases.

\textbf{Case 1.} If the sequence $\{y_{k}\}$ is not periodic, then the points $\{y_k\}$ are pairwise distinct. By Theorem~\ref{thm:main-results}\,(\ref{item:main-LipSh}) there exists an exact trajectory $\{x_k\}$ of diffeomorphism $f$ that $M\delta$-shadows~$\{y_k\}$:
\begin{equation}\label{eq:robustykxk}
    |y_k-x_k| \leq M\delta, \quad x_{k+1} = f(x_k), \quad k \in \mathbb{Z}.    
\end{equation}
Denote $A_k = Df(x_k)$. According to \eqref{eq:delta1}, \eqref{eq:delta2} the following holds
\begin{equation}\label{eq:robustAkBk}
\|A_k - B_k\| \leq \|A_k - Df(y_k)\| + \|Df(y_k) - B_k\| \leq \varepsilon/2 + \delta < \varepsilon.
\end{equation}
By item (Robust1) in Lemma \ref{lem:CL-robust-Ak}, the sequence $\{B_k\}$ satisfies generalized hyperbolicity with constants $C_1, \lambda_1$. 

\textbf{Case 2.} Suppose that the sequence $\{y_{k}\}$ is $m$-periodic. Then the sequence $\{B_k\}$ is $m$-periodic as well. By Theorem~\ref{thm:main-results}\,(\ref{item:main-LipPerSh}), there exists an $m$-periodic exact trajectory $\{x_k\}$ satisfying \eqref{eq:robustykxk}. The sequence $\{A_k = Df(x_k)\}$ is $m$-periodic and satisfies \eqref{eq:robustAkBk}. By item (Robust2) in Lemma \ref{lem:CL-robust-Ak}, the sequence $\{B_k\}$ satisfies $m$-periodic generalized hyperbolicity with constants $C_1, \lambda_1$. 

In both cases denote the spaces corresponding to generalized hyperbolicity for $\{B_k\}$ by $\tilde{E}_k^s$, $\tilde{E}_k^u$. Define (slightly abusing notation) for point~$y_k$ the spaces 
\begin{equation}\label{eq:Eg}
    \tilde{E}_{y_k}^{s, u} := \tilde{E}_k^{s, u}.    
\end{equation}
If $\omega$ is an $m$-periodic trajectory, then $\tilde{E}_k^{s, u} = \tilde{E}_{k+m}^{s, u}$, and hence $\tilde{E}_{y_k}^{s, u}$ is well-defined. Moreover, Definition \ref{def:CLf} does not impose any condition on the dependence of $E_y^{s, u}$ and the corresponding projections on the point $y$. Hence the splitting defined by \eqref{eq:Eg} satisfies the conditions of generalized hyperbolicity in Definition \ref{def:CLf}.

\label{def:CL-cocycle}
    We say that the pair $(\alpha, A)$ satisfies \textit{cocycle generalized hyperbolicity} if there exist $C > 0$, $\lambda \in (0, 1)$ and a family of projections $P_x, Q_x: \mathbb{B} \to \mathbb{B}$ satisfying the following. 
\begin{itemize}
    \item[(C-GH1)] \textbf{Splitting.} $P_x + Q_x = Id$, $\|P_x\|, \|Q_x\| \leq C$. \\Denote $E^s_x = P_x(\mathbb{B}), E^u_x = Q_x(\mathbb{B})$; then $E^s_x \oplus E^u_x = \mathbb{B}$.
    \item[(C-GH2)] \textbf{Inclusion.} $A(x)E^s_x \subseteq E^s_{\alpha(x)}$, $A^{-1}(x)E^u_{\alpha(x)} \subseteq E^u_{x}$,
    \item[(C-GH3)] \textbf{Exponential estimates.}
    $$
    |A^n_{\alpha}(x)v^s_x| \leq C \lambda^n |v^s_x|, \quad v^s_x \in E^s_x, n  \geq 0;
    $$
    $$
    |A^{-n}_{\alpha}(x)v^u_x| \leq C \lambda^n |v^u_x|, \quad v^u_x \in E^u_x, n  \geq 0.
    $$
\end{itemize}
If, additionally, $\alpha$ and $\alpha^{-1}$ are uniformly continuous and the projections $P_x$, $Q_x$ depend uniformly continuously on $x$, i.e. satisfy \eqref{eq:cont-PQ}, then we say that $(\alpha,A)$ satisfies \textit{uniformly continuous cocycle generalized hyperbolicity}.

\label{lem:SS1}
Assume that $(\alpha, A)$ satisfies the uniformly continuous cocycle generalized hyperbolicity with constants~$C, \lambda$. Then there exists $L = L(\lambda, C)$, such that the restriction $T_{\alpha, A}: Y \to X$ is a bijection and admits a bounded inverse  
\begin{equation}\label{eq:Sf}
S_{\alpha, A} = T^{-1}_{\alpha, A}: X \to Y, \quad \|S_{\alpha, A}\| \leq L.
\end{equation}

\label{lem:SS2}
    Assume that the pair $(\alpha, A)$ satisfies uniformly continuous cocycle generalized hyperbolicity with constants $C > 0$, $\lambda \in (0, 1)$. Then for any $\lambda_1 \in (\lambda, 1)$ and $\varepsilon >0$ there exist $C_1 > 1$ and $\delta >0$ such that for any homeomorphism $\beta: \mathbb{B} \to \mathbb{B}$, with $\beta$ and $\beta^{-1}$ uniformly continuous, satisfying 
\begin{equation}\label{eq:al-be-ep}
    |\alpha(x) - \beta(x)|, |\alpha^{-1}(x) - \beta^{-1}(x)| < \delta, \quad x \in \mathbb{B}    
\end{equation}
 there exist mappings $H^s_x: E_x^s \to F_x \subset E_x^u$, $H^u_{x}: E_{\alpha(x)}^u \to A(x)E_x^s \subset E_{\alpha(x)}^s$ that depend uniformly continuously on $x$ such that
    $
    \|H^s_x\|, \|H^u_x\| < \varepsilon
    $
    and the pair $(\beta, A)$ satisfies uniformly continuous cocycle generalized hyperbolicity with constants $(C_1, \lambda_1)$ and spaces 
\begin{align*}
    \tilde{E}_x^s &= (Id + H^s_x)E^s_x = \{v+H^s_x v: v \in E^s_x\},\\
        \tilde{E}_{\beta(x)}^u &= (Id + H^u_x)E^u_{\alpha(x)} = \{v+H^u_x v: v \in E^u_{\alpha(x)}\}.    
\end{align*}
There exists $\varepsilon_0$ such that if $\varepsilon < \varepsilon_0$ then 
\begin{equation}\label{eq:tildeE-EF}
    \tilde{E}^s_x \oplus A^{-1}(x)\tilde{E}^u_{\beta(x)} = E^s_x \oplus F_x.
\end{equation}

\label{thm:app-Mane}
A $C^1$-diffeomorphism $f:M\to M$ is structurally stable if and only if
\begin{equation}
\label{eq:app-Mane}
B^+(p)+B^-(p)=T_pM
\qquad\text{for every }p\in M.
\end{equation}

\label{stat:uniform-CL-finite}
Assume that $f$ satisfies Axiom~A and the strong transversality condition.
Then there exist constants $C_0>0$ and $\lambda_0\in(0,1)$ such that, for every $p\in M$, the derivative sequence
$
\left\{
Df(f^k(p)):T_{f^k(p)}M\to T_{f^{k+1}(p)}M
\right\}_{k\in\mathbb{Z}}
$
has a $(C_0,\lambda_0)$-structure in the sense of \cite{PilCL}.
